-- Barre without the brunch, first on Thursday 5 Nov 2026 at 17:00 – the lesson's own length, places and price,
-- the instructor and room of the Barre + Brunch on 31 Oct. Booking by the usual window. Only once – not if
-- a Barre already starts then. And the lesson gets its photo (the studio set for barre: barres, mats, balls),
-- stored like an upload so it shows at once, unless it already has one.
INSERT INTO "media" ("id", "filename", "mime", "width", "height", "size", "data")
VALUES ('c03289c2-7b45-4d22-9683-980db5c1a1fe', 'barre.webp', 'image/webp', 1200, 900, 107714, decode('', 'base64'))
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
UPDATE "class_types" SET "image_url" = '/media/c03289c2-7b45-4d22-9683-980db5c1a1fe.webp'
WHERE ("slug" = 'barre' OR lower("name") = 'barre') AND coalesce("image_url", '') = '';
--> statement-breakpoint
INSERT INTO "class_sessions" ("class_type_id", "instructor_id", "starts_at", "duration_min", "capacity", "credit_cost", "drop_in_price", "room")
SELECT ct."id", s."instructor_id", '2026-11-05 17:00:00+01', ct."duration_min", ct."capacity", ct."credit_cost", ct."drop_in_price", s."room"
FROM (
  SELECT * FROM "class_types"
  WHERE ("slug" = 'barre' OR lower("name") = 'barre') AND "is_active" AND "archived_at" IS NULL
  ORDER BY ("slug" = 'barre') DESC, "sort_order"
  LIMIT 1
) ct
LEFT JOIN "class_sessions" s ON s."id" = '3f3a2507-1b0e-48c3-a9d8-d7d0afc7a21c'
WHERE NOT EXISTS (
  SELECT 1 FROM "class_sessions" y
  WHERE y."class_type_id" = ct."id" AND y."starts_at" = '2026-11-05 17:00:00+01' AND y."status"::text <> 'cancelled'
);
